// ===========================================================================
//  Trajectory Simplification Visualizer — vanilla JS, no build step.
//
//  Loads the JSON trace emitted by `simplify --web-server` and replays the
//  streaming delta-simplification algorithm step by step on a <canvas>:
//  the delta-disk grid candidates P, the free-space wedge F(S,p) for every
//  surviving candidate, the incoming delta-disk hull Gi, and the resulting
//  intersection S = F ∩ Gi at each step of each "prefix" (one longest-stab
//  call).
// ===========================================================================

(function () {
  "use strict";

  // -------------------------------------------------------------------------
  //  State
  // -------------------------------------------------------------------------

  const state = {
    data: null,          // parsed trace JSON
    prefixIdx: 0,
    stepIdx: 0,           // index into prefixes[prefixIdx].steps; -1 = "before first step"
    view: { scale: 1, ox: 0, oy: 0 }, // world->screen: screen = world*scale + offset
    dragging: false,
    dragLast: null,
    playing: false,
    playTimer: null,
  };

  const layers = {
    bbox: true, stream: true, simplified: true,
    Gi: true, F: true, S: true, P: true, dead: false, buffer: true,
    onlyBest: false,
  };

  // -------------------------------------------------------------------------
  //  DOM refs
  // -------------------------------------------------------------------------

  const canvas = document.getElementById("canvas");
  const ctx = canvas.getContext("2d");
  const canvasWrap = document.getElementById("canvasWrap");
  const dropHint = document.getElementById("dropHint");
  const fileInput = document.getElementById("fileInput");
  const loadBtn = document.getElementById("loadBtn");
  const fileNameEl = document.getElementById("fileName");
  const paramsBar = document.getElementById("paramsBar");

  const prefixLabel = document.getElementById("prefixLabel");
  const prefixSlider = document.getElementById("prefixSlider");
  const stepLabel = document.getElementById("stepLabel");
  const stepSlider = document.getElementById("stepSlider");
  const statusGrid = document.getElementById("statusGrid");
  const speedSlider = document.getElementById("speedSlider");
  const speedLabel = document.getElementById("speedLabel");
  const playBtn = document.getElementById("playBtn");

  for (const key of Object.keys(layers)) {
    const el = document.getElementById("toggle-" + key);
    if (el) {
      el.checked = layers[key];
      el.addEventListener("change", () => { layers[key] = el.checked; draw(); });
    }
  }

// ===========================================================================
//  Trajectory Simplification Visualizer
// ===========================================================================
//
// Renders the JSON trace produced by `./build/simplify --web-server` on a
// pan/zoomable Canvas, with prefix/step scrubbers replaying the streaming
// simplification algorithm's intermediate structures (P, Gi, F, S, buffer).
"use strict";

(function () {
  const canvas = document.getElementById("canvas");
  const ctx = canvas.getContext("2d");
  const canvasWrap = document.getElementById("canvasWrap");
  const dropHint = document.getElementById("dropHint");
  const fileInput = document.getElementById("fileInput");
  const loadBtn = document.getElementById("loadBtn");
  const fileNameEl = document.getElementById("fileName");
  const paramsBar = document.getElementById("paramsBar");
  const statusGrid = document.getElementById("statusGrid");

  // ---- state ---------------------------------------------------------
  let data = null;           // parsed trace JSON
  let prefixIdx = 0;
  let stepIdx = -1;          // -1 = "before first step" (only P shown)
  let view = { x: 0, y: 0, scale: 1 }; // world->screen: screen = (world - {x,y}) * scale + center
  let dragging = false;
  let dragStart = null;
  let playTimer = null;

  const layers = {
    bbox: true, stream: true, simplified: true,
    Gi: true, F: true, S: true, P: true, dead: false, buffer: true,
    onlyBest: false,
  };
  for (const key of Object.keys(layers)) {
    const el = document.getElementById("toggle-" + key);
    if (el) {
      el.checked = layers[key];
      el.addEventListener("change", () => { layers[key] = el.checked; render(); });
    }
  }

  // ---- colors ----------------------------------------------------------
  const COLORS = {
    bbox: "#555b6b",
    stream: "#5a6272",
    simplified: "#3ddc97",
    Gi: "#e8c547",
    F: "#4f9dff",
    S: "#3ddc97",
    P: "#ff9f43",
    dead: "#ff5f6d",
    buffer: "#ff2fd0",
    p0: "#ffffff",
    pi: "#ffe066",
  };

// ===========================================================================
// Trajectory Simplification Visualizer — viewer.js
// ===========================================================================
//
// Self-contained, dependency-free renderer for the JSON trace produced by
// `simplify --web-server`. Loads the trace, lets the user scrub through
// prefixes (calls to get_longest_stab) and steps (points consumed within a
// prefix), and draws every intermediate structure: the bbox, the full input
// stream, the delta-disk hull G_i, the free-space wedges F(S,p) for each
// candidate anchor, the resulting stab regions S, and the running simplified
// output.

(() => {
  'use strict';

  // -------------------------------------------------------------------------
  // State
  // -------------------------------------------------------------------------
  const state = {
    trace: null,      // parsed JSON
    prefixIdx: 0,      // which prefix (get_longest_stab call)
    stepIdx: 0,        // which step within the current prefix (-1 = before any step)
    // view transform: world -> screen is  screen = (world - offset) * scale + [cx, cy]... we use a simple pan/zoom model below
    view: { scale: 1, tx: 0, ty: 0 },
    dragging: false,
    lastMouse: null,
    playing: false,
    playTimer: null,
  };

  // -------------------------------------------------------------------------
  // DOM refs
  // -------------------------------------------------------------------------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const canvasWrap = document.getElementById('canvasWrap');
  const dropHint = document.getElementById('dropHint');
  const fileInput = document.getElementById('fileInput');
  const loadBtn = document.getElementById('loadBtn');
  const fileNameEl = document.getElementById('fileName');
  const paramsBar = document.getElementById('paramsBar');
  const statusGrid = document.getElementById('statusGrid');

  const prefixSlider = document.getElementById('prefixSlider');
  const prefixLabel = document.getElementById('prefixLabel');
  const stepSlider = document.getElementById('stepSlider');
  const stepLabel = document.getElementById('stepLabel');

  const prefixFirst = document.getElementById('prefixFirst');
  const prefixPrev = document.getElementById('prefixPrev');
  const prefixNext = document.getElementById('prefixNext');
  const prefixLast = document.getElementById('prefixLast');
  const stepFirst = document.getElementById('stepFirst');
  const stepPrev = document.getElementById('stepPrev');
  const stepNext = document.getElementById('stepNext');
  const stepLast = document.getElementById('stepLast');

  const playBtn = document.getElementById('playBtn');
  const speedSlider = document.getElementById('speedSlider');
  const speedLabel = document.getElementById('speedLabel');
  const fitBtn = document.getElementById('fitBtn');
  const resetZoomBtn = document.getElementById('resetZoomBtn');

  const toggles = {};
  ['bbox', 'stream', 'simplified', 'Gi', 'F', 'S', 'P', 'dead', 'buffer', 'onlyBest'].forEach(name => {
    toggles[name] = document.getElementById('toggle-' + name);
  });

  const COLORS = {
    bbox: '#555b6b',
    stream: '#5a6272',
    simplified: '#3ddc97',
    Gi: '#e8c547',
    F: '#4f9dff',
    S: '#3ddc97',
    P: '#ff9f43',
    dead: '#ff5f6d',
    buffer: '#ff2fd0',
    p0: '#ffffff',
    pi: '#ffffff',
  };

// ===========================================================================
//  Trajectory Simplification Visualizer — viewer logic
// ===========================================================================
//
// Consumes the JSON trace produced by `simplify --web-server` and renders an
// interactive step-through of the paper's streaming construction: for each
// "prefix" (one call to get_longest_stab) it shows the delta-disk candidate
// anchors P, and for each step within a prefix it shows the point p_i being
// consumed, the delta-disk hull G_i, each surviving candidate's free-space
// wedge F(S,p) fed into intersect(), the resulting stab region S, and the
// best (buffer) segment chosen so far.

(() => {
  "use strict";

  // -------------------------------------------------------------------------
  //  State
  // -------------------------------------------------------------------------

  const state = {
    trace: null,        // parsed JSON
    prefixIdx: 0,
    stepIdx: 0,          // -1 means "before any step" (only P anchors, no consumption yet)
    cam: { x: 0, y: 0, scale: 1 }, // world->screen: screen = (world - cam) * scale + center
    dragging: false,
    dragStart: null,
    camStart: null,
    playing: false,
    playTimer: null,
  };

  // -------------------------------------------------------------------------
  //  DOM refs
  // -------------------------------------------------------------------------

  const el = (id) => document.getElementById(id);
  const canvas = el("canvas");
  const ctx = canvas.getContext("2d");
  const canvasWrap = el("canvasWrap");
  const dropHint = el("dropHint");
  const fileInput = el("fileInput");
  const loadBtn = el("loadBtn");
  const fileName = el("fileName");
  const paramsBar = el("paramsBar");
  const statusGrid = el("statusGrid");

  const prefixLabel = el("prefixLabel");
  const prefixSlider = el("prefixSlider");
  const stepLabel = el("stepLabel");
  const stepSlider = el("stepSlider");
  const speedSlider = el("speedSlider");
  const speedLabel = el("speedLabel");
  const playBtn = el("playBtn");

  const toggles = {};
  for (const key of ["bbox", "stream", "simplified", "Gi", "F", "S", "P", "dead", "buffer", "onlyBest"]) {
    toggles[key] = el(`toggle-${key}`);
  }

  // -------------------------------------------------------------------------
  //  File loading
  // -------------------------------------------------------------------------

  function loadTraceText(text, name) {
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch (e) {
      alert("Could not parse JSON: " + e.message);
      return;
    }
    if (!parsed || !Array.isArray(parsed.prefixes)) {
      alert("This does not look like a simplify --web-server trace (missing 'prefixes').");
      return;
    }
    state.trace = parsed;
    state.prefixIdx = 0;
    state.stepIdx = parsed.prefixes.length && parsed.prefixes[0].steps.length ? 0 : -1;
    fileName.textContent = name || "trace.json";
    dropHint.style.display = "none";
    renderParamsBar();
    setupSliders();
    fitToData();
    render();
  }

  loadBtn.addEventListener("click", () => fileInput.click());
  fileInput.addEventListener("change", (e) => {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    const reader = new FileReader();
    reader.onload = () => loadTraceText(reader.result, f.name);
    reader.readAsText(f);
  });

  ["dragenter", "dragover"].forEach((evt) =>
    canvasWrap.addEventListener(evt, (e) => {
      e.preventDefault();
      e.stopPropagation();
    })
  );
  canvasWrap.addEventListener("drop", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const f = e.dataTransfer.files && e.dataTransfer.files[0];
    if (!f) return;
    const reader = new FileReader();
    reader.onload = () => loadTraceText(reader.result, f.name);
    reader.readAsText(f);
  });

  // -------------------------------------------------------------------------
  //  Params bar / status grid
  // -------------------------------------------------------------------------

  function renderParamsBar() {
    const t = state.trace;
    if (!t) { paramsBar.innerHTML = ""; return; }
    const fmt = (v) => (typeof v === "number" ? (Math.abs(v) >= 1000 ? v.toFixed(1) : v.toFixed(4)) : v);
    paramsBar.innerHTML = `
      <span>&epsilon; <b>${fmt(t.eps)}</b></span>
      <span>&delta; <b>${fmt(t.delta)}</b></span>
      <span>grid_val <b>${fmt(t.grid_val)}</b></span>
      <span>R (disk radius) <b>${fmt(t.r_val)}</b></span>
      <span>a-priori Fr&eacute;chet bound <b>${fmt(t.expected_frechet)}</b></span>
      <span>time <b>${fmt(t.time_ms)} ms</b></span>
      <span>|stream| <b>${t.stream.length}</b></span>
      <span>|simplified| <b>${t.simplified.length}</b></span>
      <span>ratio <b>${(100 * t.simplified.length / t.stream.length).toFixed(1)}%</b></span>
    `;
  }

  function currentPrefix() {
    if (!state.trace) return null;
    return state.trace.prefixes[state.prefixIdx] || null;
  }

  function currentStep() {
    const pfx = currentPrefix();
    if (!pfx || state.stepIdx < 0) return null;
    return pfx.steps[state.stepIdx] || null;
  }

  function renderStatus() {
    const pfx = currentPrefix();
    const step = currentStep();
    if (!pfx) { statusGrid.innerHTML = ""; return; }
    const rows = [];
    rows.push(["p0 (anchor)", ptStr(pfx.p0)]);
    rows.push(["|P| candidates", pfx.P.length]);
    if (step) {
      const alive = step.candidates.filter((c) => c.alive).length;
      rows.push(["stream index", step.stream_idx]);
      rows.push(["p_i consumed", ptStr(step.pi)]);
      rows.push(["alive / total", `${alive} / ${step.candidates.length}`]);
      rows.push(["buffer[0]", ptStr(step.buffer[0])]);
