// -------------------------------------------------------------------------
//  Prefix / step navigation
// -------------------------------------------------------------------------

function setupSliders() {
  const t = state.trace;
  prefixSlider.max = String(Math.max(0, t.prefixes.length - 1));
  prefixSlider.value = "0";
  updateStepSliderBounds();
}

function updateStepSliderBounds() {
  const pfx = currentPrefix();
  const n = pfx ? pfx.steps.length : 0;
  // stepIdx range is [-1, n-1]; slider uses [0, n] where 0 == "before first step".
  stepSlider.min = "0";
  stepSlider.max = String(Math.max(0, n));
  stepSlider.value = String(state.stepIdx + 1);
}

function clampPrefix(i) {
  const t = state.trace;
  if (!t) return 0;
  return Math.max(0, Math.min(t.prefixes.length - 1, i));
}

function goToPrefix(i, keepStep) {
  if (!state.trace) return;
  state.prefixIdx = clampPrefix(i);
  const pfx = currentPrefix();
  if (!keepStep) state.stepIdx = pfx && pfx.steps.length ? 0 : -1;
  else state.stepIdx = pfx ? Math.max(-1, Math.min(pfx.steps.length - 1, state.stepIdx)) : -1;
  prefixSlider.value = String(state.prefixIdx);
  updateStepSliderBounds();
  render();
}

function goToStep(i) {
  const pfx = currentPrefix();
  if (!pfx) return;
  const n = pfx.steps.length;
  if (i < -1) {
    // Wrap to previous prefix's last step.
    if (state.prefixIdx > 0) {
      goToPrefix(state.prefixIdx - 1, true);
      const prevPfx = currentPrefix();
      state.stepIdx = prevPfx.steps.length - 1;
      stepSlider.value = String(state.stepIdx + 1);
      render();
    }
    return;
  }
  if (i > n - 1) {
    // Advance to next prefix's first step.
    if (state.prefixIdx < state.trace.prefixes.length - 1) {
      goToPrefix(state.prefixIdx + 1, true);
    }
    return;
  }
  state.stepIdx = i;
  stepSlider.value = String(state.stepIdx + 1);
  render();
}

el("prefixFirst").addEventListener("click", () => goToPrefix(0));
el("prefixPrev").addEventListener("click", () => goToPrefix(state.prefixIdx - 1));
el("prefixNext").addEventListener("click", () => goToPrefix(state.prefixIdx + 1));
el("prefixLast").addEventListener("click", () => state.trace && goToPrefix(state.trace.prefixes.length - 1));
prefixSlider.addEventListener("input", () => goToPrefix(parseInt(prefixSlider.value, 10)));

el("stepFirst").addEventListener("click", () => goToStep(-1));
el("stepPrev").addEventListener("click", () => goToStep(state.stepIdx - 1));
el("stepNext").addEventListener("click", () => goToStep(state.stepIdx + 1));
el("stepLast").addEventListener("click", () => {
  const pfx = currentPrefix();
  if (pfx) goToStep(pfx.steps.length - 1);
});
stepSlider.addEventListener("input", () => goToStep(parseInt(stepSlider.value, 10) - 1));

function advance() {
  const pfx = currentPrefix();
  if (!pfx) return;
  if (state.stepIdx < pfx.steps.length - 1) {
    goToStep(state.stepIdx + 1);
  } else if (state.prefixIdx < state.trace.prefixes.length - 1) {
    goToPrefix(state.prefixIdx + 1, true);
  } else {
    stopPlaying();
  }
}

function startPlaying() {
  if (!state.trace || state.playing) return;
  state.playing = true;
  playBtn.innerHTML = "&#10074;&#10074; Pause";
  const tick = () => {
    advance();
    state.playTimer = setTimeout(tick, parseInt(speedSlider.value, 10));
  };
  tick();
}
function stopPlaying() {
  state.playing = false;
  playBtn.innerHTML = "&#9654; Play";
  if (state.playTimer) clearTimeout(state.playTimer);
  state.playTimer = null;
}
playBtn.addEventListener("click", () => (state.playing ? stopPlaying() : startPlaying()));
speedSlider.addEventListener("input", () => { speedLabel.textContent = speedSlider.value + "ms"; });

window.addEventListener("keydown", (e) => {
  if (!state.trace) return;
  if (e.key === " ") { e.preventDefault(); state.playing ? stopPlaying() : startPlaying(); return; }
  if (e.key === "ArrowRight") {
    e.preventDefault();
    if (e.shiftKey) goToPrefix(state.prefixIdx + 1);
    else goToStep(state.stepIdx + 1);
  } else if (e.key === "ArrowLeft") {
    e.preventDefault();
    if (e.shiftKey) goToPrefix(state.prefixIdx - 1);
    else goToStep(state.stepIdx - 1);
  }
});

