  // -------------------------------------------------------------------------
  //  Drawing helpers
  // -------------------------------------------------------------------------

  function drawPolyline(pts, close) {
    if (!pts || pts.length < 2) return;
    ctx.beginPath();
    const [x0, y0] = worldToScreen(pts[0][0], pts[0][1]);
    ctx.moveTo(x0, y0);
    for (let i = 1; i < pts.length; ++i) {
      const [x, y] = worldToScreen(pts[i][0], pts[i][1]);
      ctx.lineTo(x, y);
    }
    if (close) ctx.closePath();
  }

  function fillPolygon(pts, fillStyle, strokeStyle, lineWidth) {
    if (!pts || pts.length < 3) return;
    drawPolyline(pts, true);
    if (fillStyle) { ctx.fillStyle = fillStyle; ctx.fill(); }
    if (strokeStyle) {
      ctx.strokeStyle = strokeStyle;
      ctx.lineWidth = lineWidth || 1.5;
      ctx.stroke();
    }
  }

  function strokePath(pts, strokeStyle, lineWidth) {
    drawPolyline(pts, false);
    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = lineWidth || 1.5;
    ctx.stroke();
  }

  function dot(p, radius, fillStyle, strokeStyle) {
    const [x, y] = worldToScreen(p[0], p[1]);
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    if (fillStyle) { ctx.fillStyle = fillStyle; ctx.fill(); }
    if (strokeStyle) { ctx.strokeStyle = strokeStyle; ctx.lineWidth = 1.5; ctx.stroke(); }
  }

  function cross(p, radius, strokeStyle) {
    const [x, y] = worldToScreen(p[0], p[1]);
    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(x - radius, y - radius); ctx.lineTo(x + radius, y + radius);
    ctx.moveTo(x - radius, y + radius); ctx.lineTo(x + radius, y - radius);
    ctx.stroke();
  }

  // -------------------------------------------------------------------------
  //  Main render
  // -------------------------------------------------------------------------

  function render() {
    resizeCanvas();
    const rect = canvasWrap.getBoundingClientRect();
    ctx.clearRect(0, 0, rect.width, rect.height);
    renderStatus();

    const t = state.trace;
    if (!t) return;

    const pfx = currentPrefix();
    const step = currentStep();

    // 1. Bounding box.
    if (toggles.bbox.checked && t.bbox) {
      const [xmin, ymin, xmax, ymax] = t.bbox;
      fillPolygon(
        [[xmin, ymin], [xmax, ymin], [xmax, ymax], [xmin, ymax]],
        null,
        "#3a4152",
        1
      );
    }

    // 2. Full input stream (faint polyline + faint dots).
    if (toggles.stream.checked) {
      strokePath(t.stream, "#3d4456", 1.25);
      ctx.fillStyle = "#4a5266";
      for (const p of t.stream) {
        const [x, y] = worldToScreen(p[0], p[1]);
        ctx.beginPath(); ctx.arc(x, y, 1.6, 0, Math.PI * 2); ctx.fill();
      }
    }

    // 3. Simplified output committed so far (all prior prefixes' outputs).
    if (toggles.simplified.checked) {
      const committed = [];
      for (let i = 0; i < state.prefixIdx; ++i) {
        committed.push(t.prefixes[i].output[0], t.prefixes[i].output[1]);
      }
      if (pfx) committed.push(pfx.output[0]);
      strokePath(committed, "#3ddc97", 2.25);
      for (const p of committed) dot(p, 2.5, "#3ddc97");
    }

    if (pfx) {
      // Determine "best" candidate index for this step (the one the buffer
      // was pulled from — mirrors the reverse scan in get_longest_stab).
      let bestIdx = -1;
      if (step) {
        for (let i = step.candidates.length - 1; i >= 0; --i) {
          const c = step.candidates[i];
          if (!c.alive || !c.S || c.S.length === 0) continue;
          bestIdx = i;
          break;
        }
      }
      const onlyBest = toggles.onlyBest.checked;

      // 4. G_i delta-disk convex hull for the point being consumed this step.
      if (step && toggles.Gi.checked) {
        fillPolygon(step.Gi, "rgba(232,197,71,0.16)", "#e8c547", 1.75);
      }

      // 5/6. Per-candidate F (wedge) and S (post-intersection stab region).
      if (step) {
        for (let i = 0; i < step.candidates.length; ++i) {
          const c = step.candidates[i];
          if (onlyBest && i !== bestIdx) continue;
          if (!c.alive) continue;
          if (toggles.F.checked && c.F && c.F.length >= 3) {
            fillPolygon(c.F, "rgba(79,157,255,0.08)", "rgba(79,157,255,0.55)", 1);
          }
          if (toggles.S.checked && c.S && c.S.length >= 3) {
            fillPolygon(c.S, "rgba(61,220,151,0.18)", "#3ddc97", 1.25);
          }
        }
      }

      // 7. Dead candidate anchors.
      if (step && toggles.dead.checked) {
        for (const c of step.candidates) {
          if (c.alive) continue;
          cross(pfx.P[c.idx !== undefined ? c.idx : c.grid_pt_idx] || pfx.P[step.candidates.indexOf(c)], 4, "#ff5f6d");
        }
      }

      // 8. P candidate anchors (alive ones highlighted more).
      if (toggles.P.checked) {
        const aliveSet = step ? new Set(step.candidates.filter((c) => c.alive).map((c, idx) => idx)) : null;
        for (let i = 0; i < pfx.P.length; ++i) {
          const isAlive = !step || (step.candidates[i] && step.candidates[i].alive);
          dot(pfx.P[i], i === bestIdx ? 4.5 : 2.5, isAlive ? "#ff9f43" : "rgba(255,159,67,0.25)");
        }
      }

      // p0 anchor (large marker).
      dot(pfx.p0, 5, "#ffffff", "#161a22");

      // pi current point highlight.
      if (step) {
        dot(step.pi, 5, "rgba(232,197,71,0.25)", "#e8c547");
      }

      // 9. Buffer segment (best candidate's chosen segment so far).
      if (step && toggles.buffer.checked) {
        strokePath(step.buffer, "#ff2fd0", 2.5);
        dot(step.buffer[0], 3.5, "#ff2fd0");
        dot(step.buffer[1], 3.5, "#ff2fd0");
      }
    }
  }

  // -------------------------------------------------------------------------
  //  Boot
  // -------------------------------------------------------------------------

  resizeCanvas();
  render();
})();

