@app.route('/api/traces', methods=['GET'])
def list_traces():
    """
    GET /api/traces
    Returns a list of available preloaded trace IDs (1-50).
    """
    traces = []
    for i in range(1, 51):
        trace_dir = DATA_DIR / str(i)
        if trace_dir.exists() and (trace_dir / "original.txt").exists():
            traces.append(i)
    return jsonify({'traces': traces})

@app.route('/api/trace/<int:trace_id>', methods=['GET'])
def get_trace(trace_id):
    """
    GET /api/trace/<id>
    Query params:
      - epsilon: float (default 0.5)
      - delta: float (default 200)

    Returns JSON trace for preloaded trace ID.
    """
    trace_dir = DATA_DIR / str(trace_id)
    if not trace_dir.exists() or not (trace_dir / "original.txt").exists():
        return jsonify({'error': f'Trace {trace_id} not found'}), 404

    try:
        epsilon = float(request.args.get('epsilon', 0.5))
        delta = float(request.args.get('delta', 200))
    except ValueError:
        return jsonify({'error': 'Invalid epsilon or delta'}), 400

    try:
        # Run simplify binary
        cmd = [
            str(SIMPLIFY_BIN),
            '--in', str(trace_id),
            '-e', str(epsilon),
            '-d', str(delta),
            '--web-server'
        ]

        result = subprocess.run(
            cmd,
            cwd=REPO_ROOT,
            capture_output=True,
            text=True,
            timeout=300
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Binary execution failed',
                'stderr': result.stderr
            }), 500

        return result.stdout, 200, {'Content-Type': 'application/json'}

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Processing timeout (>5min)'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

