  const traceId = traceSelect.value;
  if (!traceId) {
    alert("Please select a trace from the dropdown");
    return;
  }
  const eps = parseFloat(epsilonInput.value);
  const delta = parseFloat(deltaInput.value);
  if (isNaN(eps) || eps <= 0 || isNaN(delta) || delta <= 0) {
    alert("Invalid epsilon or delta");
    return;
  }

  uploadStatus.textContent = "Loading preview...";
  uploadStatus.style.color = "#e8c547";
  loadTraceBtn.disabled = true;

  try {
    // First, fetch and show the original trajectory as preview
    const previewResp = await fetch(`/api/trace/${traceId}/original`);
    if (previewResp.ok) {
      const previewData = await previewResp.json();
      if (previewData.points && previewData.points.length > 0) {
        // Show preview trace immediately (simplified = stream for now)
        const previewTrace = {
          stream: previewData.points,
          simplified: previewData.points,
          prefixes: [],
          bbox: computeBBox(previewData.points),
          eps: eps,
          delta: delta,
          grid_val: 0,
          r_val: 0,
          expected_frechet: 0,
          time_ms: 0
        };
        state.trace = previewTrace;
        state.prefixIdx = 0;
        state.stepIdx = 0;
        fitToTrace();
        render();
        uploadStatus.textContent = "Preview loaded, generating...";
        uploadStatus.style.color = "#4f9dff";
      }
    }

    // Now fetch the full trace in the background
    const resp = await fetch(`/api/trace/${traceId}?epsilon=${eps}&delta=${delta}`);
    if (!resp.ok) {
      const err = await resp.json();
      throw new Error(err.error || `Server error ${resp.status}`);
    }
    const traceText = await resp.text();
    loadTraceText(traceText, `Trace ${traceId} (ε=${eps}, δ=${delta})`);
    uploadStatus.textContent = "✓ Loaded";
    uploadStatus.style.color = "#3ddc97";
  } catch (err) {
    uploadStatus.textContent = `Error: ${err.message}`;
    uploadStatus.style.color = "#ff5f6d";
  } finally {
    loadTraceBtn.disabled = false;
  }
});

