const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const logs = [];
  page.on('console', msg => logs.push(`[console.${msg.type()}] ${msg.text()}`));
  page.on('pageerror', err => logs.push(`[pageerror] ${err.message}`));

  await page.goto('http://127.0.0.1:5000/');
  await page.waitForTimeout(1000);

  // select first available trace from dropdown
  const options = await page.$$eval('#traceSelect option', opts => opts.map(o => o.value));
  console.log('options:', options);
  const traceId = options.find(v => v !== '');
  if (traceId) {
    await page.selectOption('#traceSelect', traceId);
    await page.waitForTimeout(2000);
  }

  const playBtnBox = await page.$eval('#playBtn', el => {
    const rect = el.getBoundingClientRect();
    const style = getComputedStyle(el);
    return {
      rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height },
      display: style.display,
      visibility: style.visibility,
      opacity: style.opacity,
      disabled: el.disabled,
    };
  });
  console.log('playBtn:', JSON.stringify(playBtnBox));

  const playbackBarBox = await page.$eval('#playbackBar', el => {
    const rect = el.getBoundingClientRect();
    const style = getComputedStyle(el);
    return {
      rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height },
      display: style.display,
    };
  });
  console.log('playbackBar:', JSON.stringify(playbackBarBox));

  console.log('---console logs---');
  console.log(logs.join('\n'));

  await page.screenshot({ path: '/tmp/after_load.png', fullPage: true });
  await browser.close();
})();

