(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (err) => errors.push(err.message));
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });

  await page.goto('http://127.0.0.1:5000/');
  await page.waitForTimeout(500);

  // check dropdown options
  const options = await page.$$eval('#traceSelect option', opts => opts.map(o => o.value));
  console.log('trace options:', options);

  if (options.length > 1) {
    await page.selectOption('#traceSelect', options[1]);
    // wait for load to complete
    await page.waitForTimeout(3000);
  }

  const status = await page.$eval('#uploadStatus', el => el.textContent);
  console.log('uploadStatus:', status);

  const playBtnInfo = await page.$eval('#playBtn', (btn) => {
    const rect = btn.getBoundingClientRect();
    const style = window.getComputedStyle(btn);
    return {
      rect,
      display: style.display,
      visibility: style.visibility,
      opacity: style.opacity,
      disabled: btn.disabled,
      outerHTML: btn.outerHTML.slice(0, 300),
    };
  });
  console.log('playBtn info:', JSON.stringify(playBtnInfo, null, 2));

  const playbackBarInfo = await page.$eval('#playbackBar', (el) => {
    const rect = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return { rect, display: style.display, visibility: style.visibility };
  });
  console.log('playbackBar info:', JSON.stringify(playbackBarInfo, null, 2));

  console.log('errors:', errors);

  await page.screenshot({ path: '/tmp/after_load.png', fullPage: true });

  await browser.close();
})();

