// 5/6. Per-candidate F (wedge) and S (post-intersection stab region),
// enumerated for every surviving candidate — each orange P anchor is
// an independent starting point the algorithm tries in parallel, so
// every one of them gets its wedge/stab drawn each step. The winning
// (best) candidate — the one the buffer is pulled from — is drawn
// bolder and fully opaque so it stands out among the rest.
if (step) {
  for (let i = 0; i < step.candidates.length; ++i) {
    const c = step.candidates[i];
    if (!c.alive) continue;
    const isBest = i === bestIdx;
    if (toggles.F.checked && c.F && c.F.length >= 3) {
      fillPolygon(c.F, null, isBest ? "rgba(79,157,255,0.9)" : "rgba(79,157,255,0.3)", isBest ? 2 : 1);
    }
    if (toggles.S.checked && c.S && c.S.length >= 3) {
      fillPolygon(c.S, null, isBest ? "#3ddc97" : "rgba(61,220,151,0.45)", isBest ? 1.75 : 1);
    }
  }
}

// 7. Dead candidate anchors.
if (step && toggles.dead.checked) {
  for (const c of step.candidates) {
    if (c.alive) continue;
    const anchor = pfx.P[c.idx];
    if (anchor) cross(anchor, 4, "#ff5f6d");
  }
}

// 8. P candidate anchors — alive ones in bright orange, dead ones in a
// darker, muted orange so a glance shows which starting points are
// still in play.
if (toggles.P.checked) {
  for (let i = 0; i < pfx.P.length; ++i) {
    const isAlive = !step || (step.candidates[i] && step.candidates[i].alive);
    dot(pfx.P[i], 1.2, isAlive ? "#ff9f43" : "#7a4a1f", null);
  }
}

