// This makes it much easier to see how each candidate evolves.
if (step) {
  const aliveCandidates = step.candidates
    .map((c, i) => ({ ...c, originalIdx: i }))
    .filter(c => c.alive);

  if (aliveCandidates.length > 0) {
    const cycleIdx = state.candidateIdx % aliveCandidates.length;
    const currentCandidate = aliveCandidates[cycleIdx];
    const i = currentCandidate.originalIdx;
    const c = currentCandidate;

    // Highlight the current candidate's P anchor
    if (toggles.P.checked) {
      dot(pfx.P[i], 2.5, "#ff9f43", "#ff6b1a");
    }

    // Draw F and S for this candidate only
    if (toggles.F.checked && c.F && c.F.length >= 3) {
      fillPolygon(c.F, null, "rgba(79,157,255,0.9)", 2);
    }
    if (toggles.S.checked && c.S && c.S.length >= 3) {
      fillPolygon(c.S, null, "#3ddc97", 1.75);
    }

    // Show which candidate we're looking at
    ctx.save();
    ctx.fillStyle = "#ff9f43";
    ctx.font = "12px Inter";
    const [px, py] = worldToScreen(pfx.P[i][0], pfx.P[i][1]);
    ctx.fillText(`Candidate ${i + 1}/${pfx.P.length}`, px + 10, py - 10);
    ctx.restore();
  }
}

