// 9. Buffer segment (best candidate's chosen segment so far).
// Draw with markers to show it's a single unit: >|-------|<
if (step && toggles.buffer.checked) {
  const [x0, y0] = worldToScreen(step.buffer[0][0], step.buffer[0][1]);
  const [x1, y1] = worldToScreen(step.buffer[1][0], step.buffer[1][1]);

  // Main segment line
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.strokeStyle = "#ff2fd0";
  ctx.lineWidth = 2.5;
  ctx.stroke();

  // Draw >| marker at start
  const angle0 = Math.atan2(y1 - y0, x1 - x0);
  ctx.save();
  ctx.translate(x0, y0);
  ctx.rotate(angle0);
  ctx.beginPath();
  ctx.moveTo(-8, -6);
  ctx.lineTo(0, 0);
  ctx.lineTo(-8, 6);
  ctx.strokeStyle = "#ff2fd0";
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-8, -6);
  ctx.lineTo(-8, 6);
  ctx.stroke();
  ctx.restore();

  // Draw |< marker at end
  const angle1 = Math.atan2(y0 - y1, x0 - x1);
  ctx.save();
  ctx.translate(x1, y1);
  ctx.rotate(angle1);
  ctx.beginPath();
  ctx.moveTo(-8, -6);
  ctx.lineTo(0, 0);
  ctx.lineTo(-8, 6);
  ctx.strokeStyle = "#ff2fd0";
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-8, -6);
  ctx.lineTo(-8, 6);
  ctx.stroke();
  ctx.restore();

  // Draw dots at endpoints
  dot(step.buffer[0], 1.5, "#ff2fd0", null);
  dot(step.buffer[1], 1.5, "#ff2fd0", null);
}

