window.addEventListener("keydown", (e) => {
  if (!state.trace) return;
  if (e.key === " ") { 
    e.preventDefault(); 
    if (state.playing) {
      stopPlaying();
    } else {
      // If at the end, restart from beginning
      const pfx = currentPrefix();
      if (pfx && state.prefixIdx === state.trace.prefixes.length - 1 && 
          state.stepIdx === pfx.steps.length - 1) {
        goToPrefix(0);
        goToStep(0);
      }
      startPlaying();
    }
    return;
  }
  if (e.key === "ArrowRight") {
    e.preventDefault();
    if (e.shiftKey) goToPrefix(state.prefixIdx + 1);
    else goToStep(state.stepIdx + 1);
  } else if (e.key === "ArrowLeft") {
    e.preventDefault();
    if (e.shiftKey) goToPrefix(state.prefixIdx - 1);
    else goToStep(state.stepIdx - 1);
  } else if (e.key === "c" || e.key === "C") {
    // Cycle through candidates (only if we have a current step)
    const step = currentStep();
    if (step) {
      const aliveCount = step.candidates.filter(c => c.alive).length;
      if (aliveCount > 0) {
        state.candidateIdx = (state.candidateIdx + 1) % aliveCount;
        render();
      }
    }
  }
});

