// 5/6. Show F and S for ALL alive candidates simultaneously.
// Each candidate gets their F wedge and S stab region drawn.
if (step) {
  for (let i = 0; i < step.candidates.length; ++i) {
    const c = step.candidates[i];
    if (!c.alive) continue;

    const isBest = i === bestIdx;

    // Draw F wedge with tangent lines
    if (toggles.F.checked && c.F && c.F.length >= 3) {
      // Fill the wedge region
      fillPolygon(c.F, "rgba(79,157,255,0.15)", "rgba(79,157,255,0.6)", isBest ? 2 : 1);

      // Draw the two tangent rays from P[i] to S
      // The tangent points are the first and last vertices of the arc portion in F
      // F structure: starts with arc of S, then bbox intersections
      const anchor = pfx.P[i];
      if (c.S && c.S.length >= 2) {
        // Find tangent points: first and last point of S arc in F
        // For simplicity, draw rays to first and last vertices of S
        const s0 = c.S[0];
        const sLast = c.S[c.S.length - 1];

        // Draw tangent lines
        ctx.save();
        ctx.strokeStyle = isBest ? "rgba(79,157,255,0.9)" : "rgba(79,157,255,0.4)";
        ctx.lineWidth = isBest ? 2.5 : 1.5;
        ctx.setLineDash([4, 4]);

        // Tangent 1
        const [ax, ay] = worldToScreen(anchor[0], anchor[1]);
        const [s0x, s0y] = worldToScreen(s0[0], s0[1]);
        ctx.beginPath();
        ctx.moveTo(ax, ay);
        ctx.lineTo(s0x, s0y);
        ctx.stroke();

        // Tangent 2
        const [sLx, sLy] = worldToScreen(sLast[0], sLast[1]);
        ctx.beginPath();
        ctx.moveTo(ax, ay);
        ctx.lineTo(sLx, sLy);
        ctx.stroke();

        ctx.setLineDash([]);
        ctx.restore();
      }
