function renderStatus() {
  const pfx = currentPrefix();
  const step = currentStep();
  if (!pfx) { statusGrid.innerHTML = ""; return; }
  const rows = [];
  const startIdx = pfx.p0_idx !== undefined ? pfx.p0_idx : "—";
  const endIdx   = pfx.end_idx  !== undefined ? pfx.end_idx  : "—";
  rows.push(["start vertex", `<span style='color:#c47aff'>#${startIdx}</span> &nbsp;${ptStr(pfx.p0)}`]);
  rows.push(["end vertex",   `<span style='color:#ff7ae8'>#${endIdx}</span>`]);
  rows.push(["|P| candidates", pfx.P.length]);
  if (step) {
    const alive = step.candidates.filter((c) => c.alive).length;
    const dead = step.candidates.length - alive;
    rows.push(["current vertex", `<span style='color:#e8c547'>#${step.stream_idx}</span> &nbsp;${ptStr(step.pi)}`]);
    rows.push(["alive candidates", `${alive} / ${step.candidates.length}`]);
    rows.push(["dead candidates", dead]);

    if (alive > 0) {
      const aliveCandidates = step.candidates
        .map((c, i) => ({ ...c, originalIdx: i }))
        .filter(c => c.alive);
      const cycleIdx = state.candidateIdx % aliveCandidates.length;
      const currentCandidate = aliveCandidates[cycleIdx];
      rows.push(["<span style='color:#ff9f43'>viewing</span>", 
                 `<span style='color:#ff9f43'>Candidate ${currentCandidate.originalIdx + 1} / ${pfx.P.length}</span>`]);
    }
  } else {
    rows.push(["step", "before first consumption"]);
    rows.push(["alive candidates", pfx.P.length]);
    rows.push(["dead candidates", 0]);
  }
  rows.push(["output segment", `<span style='color:#3ddc97'>#${startIdx} → #${endIdx}</span>`]);
  statusGrid.innerHTML = rows
    .map(([k, v]) => `<span>${k}</span><span class="mono"><b>${v}</b></span>`)
    .join("");
}

