function setFrechetResult(html) {
  frechetResult.innerHTML = html;
}

function stopFrechetPoll() {
  if (frechetPollTimer) { clearTimeout(frechetPollTimer); frechetPollTimer = null; }
  frechetJobId = null;
}

async function pollFrechet(jobId) {
  try {
    const resp = await fetch(`/api/frechet/${jobId}`);
    if (!resp.ok) { setFrechetResult(`<span class="err">Server error ${resp.status}</span>`); return; }
    const data = await resp.json();
    if (data.status === "done") {
      stopFrechetPoll();
      frechetBtn.disabled = false;
      setFrechetResult(`Fréchet: <b>${data.distance.toFixed(4)}</b>`);
    } else if (data.status === "error") {
      stopFrechetPoll();
      frechetBtn.disabled = false;
      setFrechetResult(`<span class="err">Error: ${data.error}</span>`);
    } else {
      frechetPollTimer = setTimeout(() => pollFrechet(jobId), 1200);
    }
  } catch (e) {
    stopFrechetPoll();
    frechetBtn.disabled = false;
    setFrechetResult(`<span class="err">${e.message}</span>`);
  }
}

frechetBtn.addEventListener("click", async () => {
  if (!state.trace) return;
  stopFrechetPoll();
  frechetBtn.disabled = true;
  setFrechetResult('<span style="color:var(--text-dim)">Computing…</span>');

  try {
    let body;
    if (currentTraceId) {
      body = JSON.stringify({ trace_id: currentTraceId, eps: state.trace.eps, delta: state.trace.delta });
    } else if (currentFile) {
      // Upload the raw file content alongside params
      const text = await currentFile.text();
      body = JSON.stringify({ file_content: text, eps: state.trace.eps, delta: state.trace.delta });
    } else {
      setFrechetResult('<span class="err">No source file — reload trace first</span>');
      frechetBtn.disabled = false;
      return;
    }
    const resp = await fetch("/api/frechet", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body,
    });
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      throw new Error(err.error || `HTTP ${resp.status}`);
    }
    const data = await resp.json();
    frechetJobId = data.job_id;
    pollFrechet(frechetJobId);
  } catch (e) {
    frechetBtn.disabled = false;
    setFrechetResult(`<span class="err">${e.message}</span>`);
  }
});

