// 5/6. Show F and S for the viewed candidate (cycle with C).
// When all candidates died THIS step we still show F and S so the user
// can see *why* — draw them with a muted "dead" tint instead.
if (step) {
  const allCandidates = step.candidates
    .map((c, i) => ({ ...c, originalIdx: i }));
  const aliveCandidates = allCandidates.filter(c => c.alive);

  // Pick the candidate to display: prefer alive (cycling), fall back to
  // last one with F data so the terminating step always shows something.
  let viewedCandidate = null;
  if (aliveCandidates.length > 0) {
    const cycleIdx = state.candidateIdx % aliveCandidates.length;
    viewedCandidate = aliveCandidates[cycleIdx];
  } else {
    // All dead — show the last candidate that has an F polygon.
    for (let ci = allCandidates.length - 1; ci >= 0; --ci) {
      if (allCandidates[ci].F && allCandidates[ci].F.length >= 3) {
        viewedCandidate = allCandidates[ci];
        break;
      }
    }
  }

  if (viewedCandidate) {
    const i = viewedCandidate.originalIdx;
    const c = viewedCandidate;
    const dead = !c.alive;
    const anchor = pfx.P[i];

    // F wedge.  When F == full bbox the fill floods the canvas, so detect
    // that case (4 vertices all near bbox corners) and use outline-only.
    if (toggles.F.checked && c.F && c.F.length >= 3) {
      const isBbox = (() => {
        if (c.F.length !== 4 || !state.trace) return false;
        const [xmin, ymin, xmax, ymax] = state.trace.bbox;
        const corners = [[xmin,ymin],[xmax,ymin],[xmax,ymax],[xmin,ymax]];
        return c.F.every(fp =>
          corners.some(co =>
            Math.abs(fp[0]-co[0]) < 1 && Math.abs(fp[1]-co[1]) < 1));
      })();
      if (dead) {
        // Faded red — candidate died because F ∩ Gi = ∅
        fillPolygon(c.F,
          isBbox ? null : "rgba(255,95,109,0.08)",
          isBbox ? "rgba(255,95,109,0.35)" : "rgba(255,95,109,0.7)", 1.5);
      } else if (isBbox) {
        // F = whole bbox: just show a dashed border so it's clear
        ctx.save();
        ctx.strokeStyle = "rgba(79,157,255,0.7)";
        ctx.lineWidth = 1.5;
        ctx.setLineDash([6, 4]);
        fillPolygon(c.F, null, "rgba(79,157,255,0.7)", 1.5);
        ctx.setLineDash([]);
        ctx.restore();
      } else {
        fillPolygon(c.F, "rgba(79,157,255,0.18)", "rgba(79,157,255,0.85)", 2);
      }

      // Tangent rays from anchor → S tangent points (skip when F=bbox)
      if (!isBbox && anchor && c.S && c.S.length >= 2) {
        const bboxPts = new Set(
          (state.trace.bbox ? (() => {
            const [xmin,ymin,xmax,ymax] = state.trace.bbox;
            return [[xmin,ymin],[xmax,ymin],[xmax,ymax],[xmin,ymax]];
          })() : []).map(co => `${co[0]},${co[1]}`)
        );
        // The two F vertices that are also S vertices are the tangent points.
        const tangentPts = c.F.filter(fp =>
          c.S.some(sp =>
            Math.abs(fp[0]-sp[0]) < 0.5 && Math.abs(fp[1]-sp[1]) < 0.5)
        ).slice(0, 2);
        if (tangentPts.length === 2) {
          const rayColor = dead ? "rgba(255,95,109,0.7)" : "rgba(79,157,255,1)";
          ctx.save();
          ctx.strokeStyle = rayColor;
          ctx.lineWidth = dead ? 1.5 : 2;
          ctx.setLineDash([5, 5]);
          const [ax, ay] = worldToScreen(anchor[0], anchor[1]);
          for (const tp of tangentPts) {
            const [tx, ty] = worldToScreen(tp[0], tp[1]);
            ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(tx, ty); ctx.stroke();
          }
          ctx.setLineDash([]);
          ctx.restore();
        }
      }
    }

    // S intersection region.
    if (!dead && toggles.S.checked && c.S && c.S.length >= 3) {
      fillPolygon(c.S, "rgba(61,220,151,0.18)", "#3ddc97", 2);
    }

    // Highlight the candidate's anchor dot.
    if (toggles.P.checked && anchor) {
      dot(anchor, dead ? 2 : 2.5,
        dead ? "#ff5f6d" : "#ff9f43",
        dead ? "#cc3344" : "#ff6b1a");
      ctx.save();
      ctx.fillStyle = dead ? "#ff5f6d" : "#ff9f43";
      ctx.font = "bold 12px -apple-system, BlinkMacSystemFont, sans-serif";
      const [px2, py2] = worldToScreen(anchor[0], anchor[1]);
      const label = aliveCandidates.length > 0
        ? `Cand ${i+1}/${pfx.P.length}`
        : `Cand ${i+1}/${pfx.P.length} (dead)`;
      ctx.fillText(label, px2 + 10, py2 - 7);
      ctx.restore();
    }
  }
}

// 7. Dead candidate anchors — red × marks.
if (step && toggles.dead.checked) {
  for (const c of step.candidates) {
    if (c.alive) continue;
    const anchor = pfx.P[c.idx];
    if (anchor) cross(anchor, 4, "#ff5f6d");
  }
}

// 8. P candidate anchors.
if (toggles.P.checked) {
  const aliveCandidates = step ? step.candidates
    .map((c, ii) => ({ ...c, originalIdx: ii }))
    .filter(c => c.alive) : [];
  const viewedOrigIdx = (() => {
    if (aliveCandidates.length > 0)
      return aliveCandidates[state.candidateIdx % aliveCandidates.length].originalIdx;
    if (step) {
      const all = step.candidates.map((c,ii)=>({...c,originalIdx:ii}));
      for (let ci = all.length-1; ci >= 0; --ci)
        if (all[ci].F && all[ci].F.length >= 3) return all[ci].originalIdx;
    }
    return -1;
  })();
  for (let ii = 0; ii < pfx.P.length; ++ii) {
    if (ii === viewedOrigIdx) continue;
    const isAlive = !step || (step.candidates[ii] && step.candidates[ii].alive);
    dot(pfx.P[ii], 1.2, isAlive ? "#ff9f43" : "#7a4a1f", null);
  }
}

// 9. Canvas labels: p0 (start vertex) and pi (current vertex under consideration).
// p0 — purple diamond with "p₀ #N" label.
{
  const [p0x, p0y] = worldToScreen(pfx.p0[0], pfx.p0[1]);
  const startIdx = pfx.p0_idx !== undefined ? pfx.p0_idx : "";
  ctx.save();
  // Diamond marker
  ctx.beginPath();
  ctx.moveTo(p0x, p0y - 9);
  ctx.lineTo(p0x + 7, p0y);
  ctx.lineTo(p0x, p0y + 9);
  ctx.lineTo(p0x - 7, p0y);
  ctx.closePath();
  ctx.fillStyle = "#c47aff";
  ctx.fill();
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = 1;
  ctx.stroke();
  // Label
