  ctx.fillStyle = "#ff7ae8";
  ctx.fill();
  ctx.strokeStyle = "#fff";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = "#ff7ae8";
  ctx.font = "bold 12px -apple-system, BlinkMacSystemFont, sans-serif";
  ctx.fillText(`pᵢ  #${step.stream_idx}`, pix + 12, piy + 4);
  ctx.restore();
