// Tangent rays from anchor → the two extremal vertices of S (always,
// even when F is the full bbox — that's the first step where S is new).
if (anchor && c.S && c.S.length >= 1) {
  // Find the two vertices of S with the most extreme angles seen from
  // the anchor (i.e. the tangent lines from anchor to conv(S)).
  const [ax, ay] = [anchor[0], anchor[1]];
  const angles = c.S.map(sp => Math.atan2(sp[1] - ay, sp[0] - ax));
  // Widest angular gap approach: sort by angle, find the largest gap,
  // then the two boundary vertices of that gap are the tangent points.
  const indexed = angles.map((a, i) => ({ a, i }))
    .sort((u, v) => u.a - v.a);
  let maxGap = -1, gapAfter = 0;
  for (let k = 0; k < indexed.length; k++) {
    const next = (k + 1) % indexed.length;
    let gap = indexed[next].a - indexed[k].a;
    if (gap < 0) gap += 2 * Math.PI;
    if (gap > maxGap) { maxGap = gap; gapAfter = k; }
  }
  const t1 = c.S[indexed[gapAfter].i];
  const t2 = c.S[indexed[(gapAfter + 1) % indexed.length].i];
  const rayColor = dead ? "rgba(255,95,109,0.7)" : "rgba(79,157,255,1)";
  ctx.save();
  ctx.strokeStyle = rayColor;
