  if (viewedCandidate) {
    const ci = viewedCandidate.originalIdx;
    const status = statusOf(viewedCandidate);
    const anchor = pfx.P[ci];
    if (anchor) {
      let topY = Infinity;
      for (const pt of pfx.P) {
        const [, sy] = worldToScreen(pt[0], pt[1]);
        if (sy < topY) topY = sy;
      }
      const [acx] = worldToScreen(anchor[0], anchor[1]);
      const tag = status === 'justDied' ? ' (just died)' : status === 'dead' ? ' (dead)' : '';
      const headerText = `Candidate ${ci + 1}/${pfx.P.length}${tag}`;
      ctx.save();
      ctx.font = "bold 12px -apple-system, BlinkMacSystemFont, sans-serif";
